#!/usr/bin/env python3
"""Install only the Bot Office read-only dashboard, loopback port 8765."""
import base64, getpass, grp, hashlib, io, json, os, pwd, secrets, shutil, socket, subprocess, sys, zipfile
from pathlib import Path
PAYLOAD = ''
UNIT = '''[Unit]
Description=Bot Office read-only dashboard
After=network.target
[Service]
Type=simple
User=bot-office
Group=bot-office
WorkingDirectory=/opt/bot-office
ExecStart=/usr/bin/python3 /opt/bot-office/server.py
Environment=PYTHONDONTWRITEBYTECODE=1
Restart=on-failure
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
MemoryMax=96M
CPUQuota=20%
TasksMax=32
UMask=0077
[Install]
WantedBy=multi-user.target
'''

def main():
 if os.geteuid()!=0: raise SystemExit('sudo python3 bot_office_install.py 로 실행하세요.')
 for name in ('systemctl','useradd'):
  if not shutil.which(name): raise SystemExit(name+' 명령이 필요합니다.')
 for name in ('/opt/bot-office','/etc/bot-office','/etc/systemd/system/bot-office.service'):
  if Path(name).exists(): raise SystemExit('이미 설치된 경로가 있습니다. 덮어쓰지 않고 중단: '+name)
 with socket.socket() as sock:
  try:sock.bind(('127.0.0.1',8765))
  except OSError:raise SystemExit('8765 포트가 사용 중입니다. 변경 없이 중단합니다.')
 username=input('사무실 로그인 아이디 [admin]: ').strip() or 'admin'
 if len(username)>80:raise SystemExit('아이디는 80자 이내로 정하세요.')
 password=getpass.getpass('새 비밀번호 (12자 이상, 입력 중 화면에 보이지 않음): ')
 if len(password)<12:raise SystemExit('12자 이상 비밀번호로 다시 실행하세요.')
 if password!=getpass.getpass('비밀번호 한 번 더: '):raise SystemExit('비밀번호 불일치. 변경 없이 중단합니다.')
 salt=secrets.token_bytes(32);iterations=600000
 auth={'username':username,'salt':salt.hex(),'iterations':iterations,'hash':hashlib.pbkdf2_hmac('sha256',password.encode(),salt,iterations).hex()}
 del password
 try:pwd.getpwnam('bot-office')
 except KeyError:subprocess.run(['useradd','--system','--user-group','--no-create-home','--shell','/usr/sbin/nologin','bot-office'],check=True)
 app=Path('/opt/bot-office');app.mkdir(mode=0o755)
 with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as z:
  for name in ('server.py','index.html','login.html'):
   p=app/name;p.write_bytes(z.read(name));p.chmod(0o644)
 config=Path('/etc/bot-office');config.mkdir(mode=0o750)
 gid=grp.getgrnam('bot-office').gr_gid;os.chown(config,0,gid)
 f=config/'auth.json';fd=os.open(f,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o640)
 with os.fdopen(fd,'w') as stream:json.dump(auth,stream)
 os.chown(f,0,gid)
 Path('/etc/systemd/system/bot-office.service').write_text(UNIT)
 subprocess.run(['systemctl','daemon-reload'],check=True)
 subprocess.run(['systemctl','enable','--now','bot-office.service'],check=True)
 import time,urllib.request
 for _ in range(10):
  try:
   with urllib.request.urlopen('http://127.0.0.1:8765/healthz',timeout=2) as r:
    if r.status==200:break
  except OSError:time.sleep(.5)
 else:raise SystemExit('서비스 응답 대기 실패. systemctl status bot-office --no-pager 결과를 보내주세요.')
 print('\n설치 완료: 조회 전용 · 127.0.0.1:8765 (외부 비공개)')
 print('봇 4개 서비스/코드/계좌/환경파일은 변경하지 않았습니다.')
 print('HTTPS 연결 전에는 인터넷으로 직접 접속할 수 없습니다.')
 print('\n=== 웹 포트 사용 현황 ===')
 subprocess.run(['ss','-ltn','sport = :80 or sport = :443 or sport = :8765'],check=False)
 print('\n=== 설치 상태 ===')
 subprocess.run(['systemctl','is-active','bot-office.service'],check=False)
 print('\n=== HTTPS 연결 준비 ===')
 print('사용 가능한 도메인이 있으면 채팅에 도메인 이름만 알려주세요.')
 print('없으면 도메인 없음이라고 알려주세요. 비밀번호는 보내지 마세요.')
if __name__=='__main__':main()
